INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass bereits existierende Daten immer genauer als direkt erhobene Daten sind?', 2, '[{"text": "Nein", "correct": true, "because": "Genauigkeit hängt von Quelle ab"}, {"text": "Ja", "correct": false, "because": "Primärdaten oft präziser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Quelle ist typisch für bereits gesammelte Daten?', 3, '[{"text": "Datenbank", "correct": true, "because": "Speichert bestehende Daten"}, {"text": "Umfrage", "correct": false, "because": "Primärdatenerhebung"}, {"text": "Sensor", "correct": false, "because": "Direkte Messung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Daten aus bestehenden Quellen?', 5, '[{"text": "Kosteneffizienz", "correct": true, "because": "Keine neue Erhebung nötig"}, {"text": "Zeitersparnis", "correct": true, "because": "Daten bereits verfügbar"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Datenvorteil"}, {"text": "Buntes Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Berichte sind eine Quelle für solche Daten. b) Sie sind immer aktuell.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, können veraltet sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von bestehenden Daten?', 4, '[{"text": "Datenqualität", "correct": false, "because": "Entscheidend für Zuverlässigkeit"}, {"text": "Quelle", "correct": false, "because": "Beeinflusst Validität"}, {"text": "Farbcodierung", "correct": true, "because": "Kein Analysefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Daten immer öffentlich verfügbar sind?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch intern sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft, die Qualität solcher Daten zu prüfen?', 4, '[{"text": "Quellenvalidierung", "correct": true, "because": "Überprüft Zuverlässigkeit"}, {"text": "Schnelle Nutzung", "correct": false, "because": "Ignoriert Qualität"}, {"text": "Zufallsauswahl", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Daten immer kostenlos sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Können lizenzpflichtig sein"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Daten immer aktuell?', 2, '[{"text": "Nein", "correct": true, "because": "Können veraltet sein"}, {"text": "Ja", "correct": false, "because": "Aktualität nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Quellen liefern typischerweise solche Daten?', 5, '[{"text": "Studien", "correct": true, "because": "Bestehende Analysen"}, {"text": "Statistiken", "correct": true, "because": "Gesammelte Daten"}, {"text": "Live-Sensoren", "correct": false, "because": "Primärdaten"}, {"text": "Umfragen", "correct": false, "because": "Direkte Erhebung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung solcher Daten?', 4, '[{"text": "Datenqualität", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Schnelle Nutzung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Dateidesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenbanken liefern solche Daten. b) Sie sind immer genauer als Primärdaten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Genauigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Analyse solcher Daten?', 3, '[{"text": "Quellenprüfung", "correct": false, "because": "Sichert Validität"}, {"text": "Relevanzbewertung", "correct": false, "because": "Bestimmt Nutzen"}, {"text": "Präsentationsstil", "correct": true, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Zuverlässigkeit solcher Daten prüfe?', 4, '[{"text": "Quelle und Aktualität validieren", "correct": true, "because": "Sichert Qualität"}, {"text": "Nur Datenmenge zählen", "correct": false, "because": "Ignoriert Validität"}, {"text": "Ohne Prüfung nutzen", "correct": false, "because": "Riskiert Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Daten immer objektiv sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Können verzerrt sein"}, {"text": "Ja", "correct": false, "because": "Abhängig von Quelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, relevante Daten auszuwählen?', 4, '[{"text": "Zielorientierte Prüfung", "correct": true, "because": "Sichert Relevanz"}, {"text": "Zufällige Auswahl", "correct": false, "because": "Ineffizient"}, {"text": "Schnelle Nutzung", "correct": false, "because": "Ignoriert Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind solche Daten immer intern?', 2, '[{"text": "Nein", "correct": true, "because": "Auch externe Quellen"}, {"text": "Ja", "correct": false, "because": "Externe Daten üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können solche Daten haben?', 5, '[{"text": "Veraltete Informationen", "correct": true, "because": "Nicht immer aktuell"}, {"text": "Verzerrungen", "correct": true, "because": "Abhängig von Erhebung"}, {"text": "Hohe Genauigkeit", "correct": false, "because": "Kein Nachteil"}, {"text": "Schnelle Nutzung", "correct": false, "because": "Vorteil, kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Analyse solcher Daten unwichtig?', 3, '[{"text": "Datenqualität", "correct": false, "because": "Bestimmt Zuverlässigkeit"}, {"text": "Aktualität", "correct": false, "because": "Beeinflusst Nutzen"}, {"text": "Diagrammfarben", "correct": true, "because": "Nur Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich solche Daten für eine Marktanalyse nutze?', 4, '[{"text": "Relevanz und Validität prüfen", "correct": true, "because": "Sichert Ergebnisse"}, {"text": "Nur Datenmenge nutzen", "correct": false, "because": "Ignoriert Qualität"}, {"text": "Ohne Prüfung starten", "correct": false, "because": "Riskiert Fehler"}]');
